public class Main {
    static String[] todos = new String[10];
    static int jumlah = 0;

    public static void main(String[] args) {
        tambah("Belajar Java");
        tambah("Cuci motor");
        tambah("Bayar listrik");
        hapus(9);
        System.out.println("Jumlah: " + jumlah);
        hapus(0);
        hapus(-1);
        System.out.println("Jumlah: " + jumlah);
        hapus(3);
        System.out.println("Jumlah: " + jumlah);
        ubah(1, "Belajar Java OOP");
        ubah(7, "Senam");
        System.out.println("Pertama: " + todos[0]);
    }

    static void tambah(String isi) {
        todos[jumlah] = isi;
        jumlah++;
    }

    static void hapus(int nomor) {
        if (!nomorValid(nomor)) {
            System.out.println("Nomor " + nomor + " tidak ada");
            return;
        }
        for (int i = nomor - 1; i < jumlah - 1; i++) {
            todos[i] = todos[i + 1];
        }
        jumlah--;
    }

    static boolean nomorValid(int nomor) {
        return nomor >= 1 && nomor <= jumlah;
    }

    static void ubah(int nomor, String isiBaru) {
        if (!nomorValid(nomor)) {
            System.out.println("Nomor " + nomor + " tidak ada");
            return;
        }
        todos[nomor - 1] = isiBaru;
        System.out.println("Todo " + nomor + " diubah");
    }
}

